            coords = [(r, c)]
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < height and 0 <= nc < width:
                        if (nr, nc) not in coords and original[nr][nc] == original[r][c]:
                            coords.append((nr, nc))
                            q.append((nr, nc))

            min_r, max_r = min(c[0] for c in coords), max(c[0] for c in coords)
            min_c, max_c = min(c[1] for c in coords), max(c[1] for c in coords)

            total_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            fill_ratio = comp_size / total_area

            target_components.append({
                'coords': coords,
                'color': original[r][c],
                'size': comp_size,
                'bbox': (min_r, max_r, min_c, max_c),
                'fill_ratio': fill_ratio
            })

print(f"\nFound {len(target_components)} multi-cell components")
print("\nColor 2 components:")
for c in [x for x in target_components if x['color'] == 2]:
    print(f"  size={c['size']}, bbox={c['bbox']}, fill={c['fill_ratio']:.2f}")

print("\nColor 8 components:")
for c in [x for x in target_components if x['color'] == 8]:
    print(f"  size={c['size']}, bbox={c['bbox']}, fill={c['fill_ratio']:.2f}")

from collections import deque, defaultdict

height = len(original)
width = len(original[0])
bg = 5

# Rebuild component detection with union-find
parent = {}
def find(x):
    if x not in parent:
        parent[x] = x
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]
def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

for r in range(height):
    for c in range(width):
        key = (r, c)
        color = original[r][c]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                if original[nr][nc] == color:
                    union(key, (nr, nc))

# Group cells by component root
root_to_coords = defaultdict(set)
for r in range(height):
    for c in range(width):
        root_to_coords[find((r, c))].add((r, c))

noise_colors = {1, 4, 6, 7}
noise_count = sum(1 for r in range(height) for c in range(width) if original[r][c] in noise_colors)
print(f"Noise pixels to remove: {noise_count}")

# Create output grid
output = [[5 for _ in range(width)] for _ in range(height)]

# Fill bounding boxes for each unique multi-cell component
for root, coords in root_to_coords.items():
    if len(coords) > 1:  # Multi-cell only
        color = original[list(coords)[0][0]][list(coords)[0][1]]
        min_r = min(coord[0] for coord in coords)
        max_r = max(coord[0] for coord in coords)
        min_c = min(coord[1] for coord in coords)
        max_c = max(coord[1] for coord in coords)

        # Fill entire bbox with this color
        for rr in range(min_r, max_r + 1):
            for cc in range(min_c, max_c + 1):
                output[rr][cc] = color

total_preserved = sum(1 for r in range(height) for c in range(width) if output[r][c] != bg)
print(f"Pixels preserved after transformation: {total_preserved}")

# Convert to JSON format
result = '\n'.join(' '.join(str(x) for x in row) for row in output)
print("\nResult (first 5 rows):\n")
print('\n'.join(result.split('\n')[:5]))
